draw:
var cyc = 8;
var tc = t % cyc;
var w0 = p.omega0, al = p.alpha;
var th = w0 * tc + 0.5 * al * tc * tc;
var w = w0 + al * tc;
var R = Math.min(W * 0.30, H * 0.38);
var cx = W * 0.30, cy = H * 0.52;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + R * 1.22, cy);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("theta = 0", cx + R * 0.62, cy - 6);

var k;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (k = 0; k < 4; k++) {
  var a = th + k * Math.PI / 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + R * Math.cos(a), cy - R * Math.sin(a));
  ctx.stroke();
}

var tha = Math.min(Math.abs(th), Math.PI * 2);
var end = th > 0 ? -tha : tha;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.arc(cx, cy, R * 0.42, 0, end, th > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
var mid = th > 0 ? tha / 2 : -tha / 2;
ctx.fillText("theta", cx + R * 0.55 * Math.cos(mid) - 8, cy - R * 0.55 * Math.sin(mid) + 4);

var mx = cx + R * Math.cos(th), my = cy - R * Math.sin(th);
var vlen = Math.min(Math.abs(w) * R * 0.075, R * 0.75);
var sgn = w >= 0 ? 1 : -1;
var tx = -Math.sin(th) * sgn, ty = -Math.cos(th) * sgn;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(mx, my);
ctx.lineTo(mx + tx * vlen, my + ty * vlen);
ctx.stroke();
var hx = mx + tx * vlen, hy = my + ty * vlen;
ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - tx * 7 - ty * 4, hy - ty * 7 + tx * 4);
ctx.lineTo(hx - tx * 7 + ty * 4, hy - ty * 7 - tx * 4);
ctx.closePath();
ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("v = omega r", hx + 6, hy - 4);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(mx, my, 5, 0, Math.PI * 2);
ctx.fill();

var bx = W * 0.63;
var by = H * 0.26;
var lh = Math.min(22, H * 0.13);
ctx.fillStyle = C.ink;
ctx.fillText("t     = " + tc.toFixed(2) + " s", bx, by);
ctx.fillText("omega = " + w.toFixed(2) + " rad/s", bx, by + lh);
ctx.fillText("alpha = " + al.toFixed(2) + " rad/s^2", bx, by + 2 * lh);
ctx.fillStyle = C.figure;
ctx.fillText("theta = " + th.toFixed(2) + " rad", bx, by + 3 * lh);
ctx.fillStyle = C.faint;
ctx.fillText("      = " + (th / (2 * Math.PI)).toFixed(2) + " rev", bx, by + 4 * lh);

out.note = "theta = " + th.toFixed(2) + " rad (" + (th / (2 * Math.PI)).toFixed(2) +
  " rev), omega = " + w.toFixed(2) + " rad/s at t = " + tc.toFixed(2) + " s";

var r = p.radius, w = p.omega, al = p.alpha;
var v = w * r, ac = w * w * r, at = al * r;
var atot = Math.sqrt(ac * ac + at * at);
var phi = Math.atan2(ac, at) * 180 / Math.PI;

var R = Math.min(W * 0.22, H * 0.33);
var cx = W * 0.34, cy = H * 0.55;
var th = 0.35 * t + 0.9;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(cx, cy, 3, 0, Math.PI * 2);
ctx.fill();

var px = cx + R * Math.cos(th), py = cy - R * Math.sin(th);

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(px, py);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("r = " + r.toFixed(2) + " m", cx + R * 0.35 * Math.cos(th) + 4,
  cy - R * 0.35 * Math.sin(th) - 5);

var ux = -Math.sin(th), uy = -Math.cos(th);
var nx = -Math.cos(th), ny = Math.sin(th);

var vs = Math.min(R * 0.9 / Math.max(v, 0.001), 60);
var as = Math.min(R * 1.05 / Math.max(atot, 0.001), 60);

function arrow(x0, y0, dx, dy, col, lab) {
  var L = Math.sqrt(dx * dx + dy * dy);
  if (L < 1) return;
  var ex = dx / L, ey = dy / L;
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x0 + dx, y0 + dy);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0 + dx, y0 + dy);
  ctx.lineTo(x0 + dx - ex * 8 - ey * 4.5, y0 + dy - ey * 8 + ex * 4.5);
  ctx.lineTo(x0 + dx - ex * 8 + ey * 4.5, y0 + dy - ey * 8 - ex * 4.5);
  ctx.closePath();
  ctx.fill();
  ctx.fillText(lab, x0 + dx + ex * 6 - 4, y0 + dy + ey * 6 + 4);
}

arrow(px, py, ux * v * vs, uy * v * vs, C.accent, "v = " + v.toFixed(2) + " m/s");
arrow(px, py, nx * ac * as, ny * ac * as, C.figure, "a_c = " + ac.toFixed(1));
arrow(px, py, ux * at * as, uy * at * as, C.figure, "a_t = " + at.toFixed(1));

ctx.setLineDash([2, 3]);
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(px + ux * at * as, py + uy * at * as);
ctx.lineTo(px + ux * at * as + nx * ac * as, py + uy * at * as + ny * ac * as);
ctx.moveTo(px + nx * ac * as, py + ny * ac * as);
ctx.lineTo(px + ux * at * as + nx * ac * as, py + uy * at * as + ny * ac * as);
ctx.stroke();
ctx.setLineDash([]);

arrow(px, py, (ux * at + nx * ac) * as, (uy * at + ny * ac) * as, C.ink,
  "a = " + atot.toFixed(1) + " m/s^2");

var bx = W * 0.68;
var by = H * 0.20;
var lh = Math.min(20, H * 0.12);
ctx.fillStyle = C.ink;
ctx.fillText("v   = omega r  = " + v.toFixed(2) + " m/s", bx, by);
ctx.fillText("a_t = alpha r  = " + at.toFixed(2), bx, by + lh);
ctx.fillText("a_c = omega^2 r = " + ac.toFixed(2), bx, by + 2 * lh);
ctx.fillStyle = C.accent;
ctx.fillText("angle(a, v) = " + phi.toFixed(1) + " deg", bx, by + 3 * lh);

out.note = "|a| = " + atot.toFixed(2) + " m/s^2, tilted " + phi.toFixed(1) +
  " deg from the velocity (tan = a_c / a_t = " + (ac / Math.max(at, 1e-9)).toFixed(2) + ")";

var v = p.speed, r = p.radius, ps0 = p.probe * Math.PI / 180;
var w = v / r;
var pad = W * 0.06;
var R = Math.min(H * 0.30, W * 0.13);
var ppm = R / r;
var L = (W - 2 * pad) / ppm;
var xc = (v * t) % L;
var psi = ps0 + xc / r;

var gy = H * 0.82;
var X = function (x) { return pad + x * ppm; };
var Y = function (y) { return gy - y * ppm; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(0, gy);
ctx.lineTo(W, gy);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.lineWidth = 1.5;
ctx.beginPath();
var s;
for (s = 0; s <= L; s += L / 300) {
  var q = ps0 + s / r;
  var x = s - r * Math.sin(q), y = r - r * Math.cos(q);
  s === 0 ? ctx.moveTo(X(x), Y(y)) : ctx.lineTo(X(x), Y(y));
}
ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.arc(X(xc), Y(r), R, 0, Math.PI * 2);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(X(xc), Y(r), 3, 0, Math.PI * 2);
ctx.fill();

function arrow(x0, y0, dx, dy, col, lab, dlab) {
  var Lm = Math.sqrt(dx * dx + dy * dy);
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2;
  if (Lm > 1.5) {
    var ex = dx / Lm, ey = dy / Lm;
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x0 + dx, y0 + dy);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x0 + dx, y0 + dy);
    ctx.lineTo(x0 + dx - ex * 8 - ey * 4.5, y0 + dy - ey * 8 + ex * 4.5);
    ctx.lineTo(x0 + dx - ex * 8 + ey * 4.5, y0 + dy - ey * 8 - ex * 4.5);
    ctx.closePath();
    ctx.fill();
  }
  ctx.fillText(lab, x0 + dx + 6, y0 + dy + dlab);
}

var vs = R * 0.55 / Math.max(v, 0.001);

arrow(X(xc), Y(2 * r), 2 * v * vs, 0, C.figure, "top: 2v = " + (2 * v).toFixed(1) + " m/s", -6);
arrow(X(xc), Y(r), v * vs, 0, C.figure, "axle: v = " + v.toFixed(1), -6);
arrow(X(xc) + R, Y(r), v * vs, -v * vs, C.figure,
  "side: 1.41v = " + (Math.SQRT2 * v).toFixed(1), 0);
ctx.fillStyle = C.figure;
ctx.fillText("contact: v = 0", X(xc) + 8, Y(0) - 6);
ctx.beginPath();
ctx.arc(X(xc), Y(0), 4, 0, Math.PI * 2);
ctx.fill();

var pxm = xc - r * Math.sin(psi), pym = r - r * Math.cos(psi);
var vxp = v * (1 - Math.cos(psi)), vyp = v * Math.sin(psi);
var sp = Math.sqrt(vxp * vxp + vyp * vyp);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(X(xc), Y(r));
ctx.lineTo(X(pxm), Y(pym));
ctx.stroke();

arrow(X(pxm), Y(pym), vxp * vs, -vyp * vs, C.accent, "probe " + sp.toFixed(2) + " m/s", 0);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(X(pxm), Y(pym), 5, 0, Math.PI * 2);
ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("omega = v / r = " + w.toFixed(2) + " rad/s", pad, H * 0.12);

out.note = "probe point speed " + sp.toFixed(2) + " m/s = 2v sin(psi/2), with psi = " +
  ((psi % (2 * Math.PI)) * 180 / Math.PI).toFixed(0) + " deg measured from the contact point";
